 keys=list(dict.fromkeys(r['source']for r in items))
 body+=section('Reference scope','<p>The table groups hardware by catalog family. It does not certify dimensions or current stock. For a document-level status finding, use the cross-reference page; for a dimensional table, use the linked guide.</p>'+source_note(keys),'SOURCES')
 page(familyfile(family),family.title()+' | Mil-Spec Family Reference | Webson','Identify '+family.lower()+' by military and aerospace series, compare family distinctions and prepare a complete Webson RFQ.',family.title()+'.','A family reference for specification-controlled hardware. Identify the relevant series and the details needed to source the required part.',body)
